export interface Mapping {
  /**
   * Source table in SAP DMC
   */
  source: string;

  /**
   * Target table in MESX
   */
  destination: string;
  /**
   * Cache treatment  in MESX
   */
  cacheTreatment: boolean;
  /**
  /**
   * Key fields source and associated column in target structure
   */
  keys: Array<KeyMapping>;

  /**
   * Column mapping
   */
  columnMappings: Array<ColumnMapping>;
}

export interface KeyMapping {
  /**
   * Source field
   */
  keySource: string;

  /**
   * Target field
   */
  keyDestination: string;

  /**
   * If not optional we expect to have target field valuated
   */
  optional?: boolean;
}

export interface ColumnMapping {
  /**
   * Source field
   */
  columnSource: string;

  /**
   * Target field
   */
  columnDestination: string;
  /**
   * Type field
   */
  type?: string;
  /**
   * AllowEmpty field
   */
  allowEmpty?: boolean;
}

export type MappedOutput =
  | PickingOrder
  | ProductionOrder
  | MaterialDtl
  | Buffer
  | MaterialGroup
  | MaterialGroupMember
  | Alert
  | AlertConfig
  | Workcenter
  | LauncherKpi;

export interface KeysValueArray {
  [key: string]: number | string;
}

