      { key: 'bindingMaterialGroup', value: this.bindingMaterialGroup },
      { key: 'bindingWorkCenterList', value: this.bindingWorkCenterList },
      {
        key: 'bindingMaterialGroupMember',
        value: this.bindingMaterialGroupMember,
      },
      {
        key: 'bindingAlert',
        value: this.bindingAlert,
      },
      {
        key: 'bindingAlertConfig',
        value: this.bindingAlertConfig,
      },
      {
        key: 'bindingMtlTrans',
        value: this.bindingMtlTrans,
      },
      {
        key: 'bindingLauncherKpi',
        value: this.bindingLauncherKpi,
      },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          this.context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required configurations are properly set',
      this.context,
    );
  }
